WITH scored AS (SELECT id, store_id, product_id, quantity, last_restock, FIRST_VALUE(quantity) IGNORE NULLS OVER (PARTITION BY product_id ORDER BY last_restock, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_quantity, NTILE(5) OVER (PARTITION BY store_id, product_id ORDER BY quantity, id) AS quantity_bucket, CUME_DIST() OVER (ORDER BY quantity NULLS LAST) AS quantity_cume_dist, SUM(quantity) OVER (ORDER BY last_restock, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_quantity, PERCENT_RANK() OVER (PARTITION BY store_id, product_id ORDER BY quantity DESC NULLS LAST) AS quantity_percent_rank FROM inventory) SELECT id, product_id, quantity, first_known_quantity, quantity_bucket, quantity_cume_dist, quantity_percent_rank FROM scored ORDER BY quantity DESC, id
